"""Write a fully self-contained, offline graph report."""
from __future__ import annotations

import json
from pathlib import Path


def write_html(graph: dict, center: str, root: Path, output: Path, max_nodes: int = 80) -> None:
    payload = json.dumps({"graph": graph, "center": center, "root": str(root.resolve()),
                          "maxNodes": max_nodes}, separators=(",", ":"))
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    html = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'">
<title>Code Impact Explorer</title>
<style>
:root{font:14px system-ui,sans-serif;color:#e6edf3;background:#0d1117}*{box-sizing:border-box}body{margin:0;display:grid;grid-template-columns:270px 1fr 300px;height:100vh}aside{padding:18px;overflow:auto;background:#161b22;border-right:1px solid #30363d}aside:last-child{border-right:0;border-left:1px solid #30363d}h1{font-size:18px;margin:0 0 4px}h2{font-size:14px;margin:20px 0 8px;color:#8b949e}p,small{color:#8b949e;line-height:1.45}label{display:block;margin:12px 0 5px}input,select,button{font:inherit;color:#e6edf3;background:#21262d;border:1px solid #484f58;border-radius:6px;padding:7px}input[type=search],select{width:100%}input[type=range]{width:100%}button{cursor:pointer;margin:4px 4px 4px 0}button:hover,a:hover{border-color:#58a6ff;color:#58a6ff}a{color:#58a6ff;overflow-wrap:anywhere}main{position:relative;overflow:hidden;background:radial-gradient(circle at center,#18212e,#0d1117)}svg{width:100%;height:100%;touch-action:none}.edge{stroke:#7d8590;stroke-width:1.5;fill:none}.edge.unresolved{stroke:#e3b341;stroke-dasharray:5 5}.node rect{fill:#21262d;stroke:#58a6ff;stroke-width:1.5;rx:8}.node.unresolved rect{stroke:#e3b341;stroke-dasharray:5 4}.node.center rect{fill:#1f3b54;stroke-width:3}.node.changed rect{stroke:#f78166}.node text{fill:#e6edf3;font-size:13px;pointer-events:none}.node .meta{fill:#8b949e;font-size:11px}.node{cursor:pointer}.node.search-dim{opacity:.2}.edge-hit{stroke:transparent;stroke-width:16;cursor:pointer}#status{position:absolute;bottom:12px;left:14px;padding:6px 9px;background:#161b22cc;border-radius:6px}code{overflow-wrap:anywhere;color:#d2a8ff}.badge{display:inline-block;padding:2px 6px;border-radius:5px;background:#30363d;margin-right:4px}.warn{color:#e3b341}#searchResults button{display:block;width:100%;text-align:left}.location{margin:8px 0}
</style></head><body>
<aside><h1>Code Impact Explorer</h1><small>Source-backed function call graph</small>
<label for="search">Find function</label><input id="search" type="search" placeholder="Name or file"><div id="searchResults"></div>
<h2>Explore</h2><label for="direction">Direction</label><select id="direction"><option value="both">Callers and callees</option><option value="callers">Callers only</option><option value="callees">Callees only</option></select>
<label for="depth">Maximum depth: <span id="depthValue">1</span></label><input id="depth" type="range" min="1" max="6" value="1">
<label><input id="callsFilter" type="checkbox" checked> Calls</label><label><input id="groupModule" type="checkbox" checked> Group by module</label>
<button id="reset">Reset view</button><button id="fit">Fit graph</button>
<h2>Legend</h2><p><span class="badge">Blue</span> Indexed function<br><span class="badge warn">Dashed gold</span> Unresolved or ambiguous<br><span class="badge">Coral</span> Changed symbol (future impact reports)</p>
<p>Click a node to inspect and expand it. Click again to collapse its branch. Click an edge to see its call site.</p>
</aside><main><svg id="canvas" aria-label="Interactive call graph"><g id="viewport"><g id="edges"></g><g id="nodes"></g></g></svg><div id="status"></div></main>
<aside><h2>Details</h2><div id="details">Select a node or edge.</div><h2>Coverage</h2><div id="coverage"></div></aside>
<script id="data" type="application/json">__DATA__</script><script>
const {graph,root,maxNodes}=JSON.parse(document.getElementById('data').textContent);let center=JSON.parse(document.getElementById('data').textContent).center;
const byId=new Map(graph.nodes.map(n=>[n.id,n]));const expanded=new Set([center]);let visible=new Set(),selected=null,scale=1,tx=0,ty=0,currentLevels=new Map();
const svg=document.getElementById('canvas'),viewport=document.getElementById('viewport'),nodesG=document.getElementById('nodes'),edgesG=document.getElementById('edges');
const el=(tag,attrs={})=>{let e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(let [k,v] of Object.entries(attrs))e.setAttribute(k,v);return e};
const fileUrl=(f,line)=>'file://'+encodeURI(root+'/'+f)+(line?'#L'+line:'');
const vscodeUrl=(f,line)=>'vscode://file/'+encodeURI(root+'/'+f)+(line?':'+line:'');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function neighbors(id){let direction=document.getElementById('direction').value;if(!document.getElementById('callsFilter').checked)return [];let out=[];for(let e of graph.edges){if(e.source===id&&direction!=='callers')out.push([e.target,e]);if(e.target===id&&direction!=='callees')out.push([e.source,e])}return out}
function compute(){const maxDepth=+document.getElementById('depth').value;let q=[[center,0]],seen=new Set([center]),levels=new Map([[center,0]]);while(q.length){let [id,d]=q.shift();if(d>=maxDepth||!expanded.has(id))continue;for(let [next] of neighbors(id)){if(seen.size>=maxNodes)break;if(!seen.has(next)){seen.add(next);levels.set(next,d+1);q.push([next,d+1])}}}visible=seen;return levels}
function layout(levels){let columns=new Map();for(let id of visible){let level=levels.get(id)||0,side=0;if(id!==center){let incoming=graph.edges.some(e=>e.source===id&&e.target===center);let outgoing=graph.edges.some(e=>e.source===center&&e.target===id);side=incoming&&!outgoing?-1:outgoing&&!incoming?1:1;side*=level}if(!columns.has(side))columns.set(side,[]);columns.get(side).push(id)}let pos=new Map();for(let [column,ids] of columns){ids.sort((a,b)=>{let x=byId.get(a),y=byId.get(b);return document.getElementById('groupModule').checked?(x.module||'').localeCompare(y.module||'')||x.name.localeCompare(y.name):x.name.localeCompare(y.name)});let grouped=document.getElementById('groupModule').checked,gap=0,ys=[];ids.forEach((id,i)=>{if(grouped&&i&&byId.get(ids[i-1]).module!==byId.get(id).module)gap+=45;ys.push(i*100+gap)});let mid=(ys[0]+ys[ys.length-1])/2;ids.forEach((id,i)=>pos.set(id,{x:column*260,y:ys[i]-mid}))}return pos}
function draw(){let levels=compute(),pos=layout(levels);currentLevels=levels;nodesG.replaceChildren();edgesG.replaceChildren();let edges=graph.edges.filter(e=>visible.has(e.source)&&visible.has(e.target)&&document.getElementById('callsFilter').checked);for(let e of edges){let a=pos.get(e.source),b=pos.get(e.target);if(!a||!b)continue;let x1=a.x+(a.x<=b.x?85:-85),x2=b.x+(a.x<=b.x?-85:85),path=`M${x1},${a.y} C${(x1+x2)/2},${a.y} ${(x1+x2)/2},${b.y} ${x2},${b.y}`;let line=el('path',{d:path,class:'edge '+(e.resolution==='verified'?'':'unresolved')});edgesG.append(line);let hit=el('path',{d:path,class:'edge-hit'});hit.addEventListener('click',ev=>{ev.stopPropagation();showEdge(e)});edgesG.append(hit)}for(let id of visible){let n=byId.get(id),p=pos.get(id),g=el('g',{class:'node '+(id===center?'center ':'')+(n.resolution!=='verified'?'unresolved ':'')+(n.change_status?'changed':'')});g.setAttribute('transform',`translate(${p.x},${p.y})`);g.append(el('rect',{x:-85,y:-31,width:170,height:62}));let label=el('text',{'text-anchor':'middle',y:-4});label.textContent=n.name.length>22?n.name.slice(0,20)+'…':n.name;g.append(label);let meta=el('text',{class:'meta','text-anchor':'middle',y:17});meta.textContent=(n.module||n.resolution||'').slice(0,24);g.append(meta);g.addEventListener('click',ev=>{ev.stopPropagation();toggleNode(id);showNode(n)});nodesG.append(g)}document.getElementById('status').textContent=`${visible.size} nodes · ${edges.length} call sites${visible.size>=maxNodes?' · node limit reached':''}`;let query=document.getElementById('search').value.toLowerCase();if(query)highlight(query)}
function toggleNode(id){if(expanded.has(id)&&id!==center)expanded.delete(id);else if(id!==center){expanded.add(id);let depth=document.getElementById('depth');depth.value=Math.min(6,Math.max(+depth.value,(currentLevels.get(id)||0)+1));document.getElementById('depthValue').textContent=depth.value}draw();fit()}
function showNode(n){selected=n;let source=n.file?`<div class="location"><a href="${esc(fileUrl(n.file,n.line))}">Open source</a> · <a href="${esc(vscodeUrl(n.file,n.line))}">Open in VS Code</a><br><code>${esc(n.file)}:${n.line}</code></div>`:'';let related=graph.edges.filter(e=>e.source===n.id||e.target===n.id);document.getElementById('details').innerHTML=`<h3>${esc(n.name)}</h3><p><code>${esc(n.id)}</code></p><p>Type: ${esc(n.type)}<br>Resolution: ${esc(n.resolution)}<br>Module: ${esc(n.module||'unknown')}</p>${source}<p>${related.length} indexed call site(s)</p><button id="toggleNode" ${n.id===center?'disabled':''}>${n.id===center?'Center function':expanded.has(n.id)?'Collapse branch':'Expand direct relationships'}</button>`;document.getElementById('toggleNode').onclick=()=>{toggleNode(n.id);showNode(n)}}
function showEdge(e){let evidence=e.evidence;document.getElementById('details').innerHTML=`<h3>Call relationship</h3><p><code>${esc(byId.get(e.source)?.name)}</code> → <code>${esc(byId.get(e.target)?.name)}</code></p><p>Resolution: ${esc(e.resolution)}<br>Certainty: ${esc(e.certainty)}</p><p>Evidence: <a href="${esc(fileUrl(evidence.file,evidence.line))}">${esc(evidence.file)}:${evidence.line}:${evidence.column}</a> · <a href="${esc(vscodeUrl(evidence.file,evidence.line))}">VS Code</a></p>`}
function fit(){let items=[...nodesG.children];if(!items.length)return;let box=viewport.getBBox(),w=svg.clientWidth,h=svg.clientHeight;scale=Math.min(1.2,Math.max(.2,Math.min((w-60)/Math.max(box.width,1),(h-60)/Math.max(box.height,1))));tx=w/2-scale*(box.x+box.width/2);ty=h/2-scale*(box.y+box.height/2);transform()}
function transform(){viewport.setAttribute('transform',`translate(${tx},${ty}) scale(${scale})`)}
function highlight(query){for(let g of nodesG.children){let n=byId.get([...visible][Array.prototype.indexOf.call(nodesG.children,g)]);g.classList.toggle('search-dim',!((n?.name||'').toLowerCase().includes(query)||(n?.file||'').toLowerCase().includes(query)))}}
document.getElementById('search').oninput=ev=>{let q=ev.target.value.toLowerCase(),results=document.getElementById('searchResults');results.replaceChildren();if(!q){draw();return}for(let n of graph.nodes.filter(n=>n.type==='function'&&(n.name.toLowerCase().includes(q)||n.file?.toLowerCase().includes(q))).slice(0,8)){let b=document.createElement('button');b.textContent=n.name+' · '+n.file;b.onclick=()=>{center=n.id;expanded.clear();expanded.add(center);draw();fit();showNode(n);results.replaceChildren()};results.append(b)}draw()};
for(let id of ['direction','depth','callsFilter','groupModule'])document.getElementById(id).oninput=()=>{document.getElementById('depthValue').textContent=document.getElementById('depth').value;draw();fit()};
document.getElementById('reset').onclick=()=>{expanded.clear();expanded.add(center);document.getElementById('depth').value=1;document.getElementById('depthValue').textContent='1';draw();fit()};document.getElementById('fit').onclick=fit;
let dragging=false,lastX=0,lastY=0;svg.addEventListener('pointerdown',e=>{if(e.target===svg||e.target===edgesG){dragging=true;lastX=e.clientX;lastY=e.clientY;svg.setPointerCapture(e.pointerId)}});svg.addEventListener('pointermove',e=>{if(dragging){tx+=e.clientX-lastX;ty+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;transform()}});svg.addEventListener('pointerup',()=>dragging=false);svg.addEventListener('wheel',e=>{e.preventDefault();let factor=e.deltaY<0?1.12:1/1.12;let rect=svg.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;tx=x-(x-tx)*factor;ty=y-(y-ty)*factor;scale=Math.max(.15,Math.min(4,scale*factor));transform()},{passive:false});
document.getElementById('coverage').textContent=(graph.diagnostics.length||graph.coverage_warnings.length)?`${graph.diagnostics.length} file(s) had Clang diagnostics; ${graph.coverage_warnings.length} coverage warning(s). Some relationships may be missing. See CLI index output.`:'No Clang diagnostics or coverage warnings were recorded. Indirect calls and conditional builds still require care.';
draw();fit();showNode(byId.get(center));
</script></body></html>'''
    output.write_text(html.replace("__DATA__", payload), encoding="utf-8")
